def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_m, last_o = history[-1]
    prev_m = history[-2][0] if n >= 2 else 'C'

    opp_d = 0
    my_d = 0
    recent_len = min(6, n)
    recent_start = n - recent_len
    recent_opp_d = 0
    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1
        if i >= recent_start and o == 'D':
            recent_opp_d += 1

    recent_opp_c = recent_len - recent_opp_d

    my_d_next_d = 0
    my_d_next_c = 0
    my_c_next_d = 0
    my_c_next_c = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]
        if pm == 'D':
            if co == 'D':
                my_d_next_d += 1
            else:
                my_d_next_c += 1
        else:
            if co == 'D':
                my_c_next_d += 1
            else:
                my_c_next_c += 1

    d_ctx = my_d_next_d + my_d_next_c
    c_ctx = my_c_next_d + my_c_next_c
    retal_rate = float(my_d_next_d) / d_ctx if d_ctx else 1.0
    forgive_rate = float(my_d_next_c) / d_ctx if d_ctx else 0.0
    unprov_rate = float(my_c_next_d) / c_ctx if c_ctx else 0.0

    hostile = (opp_d > n * 0.5 or
              recent_opp_d > recent_len * 0.6 or
              unprov_rate > 0.35)
    forgiving = (d_ctx >= 1 and
                 forgive_rate >= 0.5 and
                 unprov_rate <= 0.35)
    rounds_left = 100 - n

    if last_o == 'C':
        if not hostile:
            if forgiving and rounds_left <= 2:
                return 'D'
            if d_ctx >= 1 and retal_rate <= 0.4 and rounds_left <= 2:
                return 'D'
            if my_d_next_c >= 2 and rounds_left <= 3 and unprov_rate <= 0.3:
                return 'D'
            if rounds_left == 2 and opp_d == 0 and my_d == 0:
                return 'D'
            if n == 45 and opp_d == 0 and my_d == 0:
                return 'D'
        return 'C'

    if hostile:
        return 'D'

    if last_m == 'C':
        if (n >= 2 and prev_m == 'D' and d_ctx >= 1 and
            my_d_next_d >= 1 and my_c_next_d == 0 and
            opp_d <= max(2, int(n * 0.25))):
            return 'C'
        return 'D'

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_streak += 1
        else:
            break

    if dd_streak >= 1:
        if forgiving and recent_opp_d <= recent_len * 0.5:
            return 'C'
        if recent_opp_c >= 2 and my_c_next_d <= 1:
            return 'C'
        if (dd_streak >= 5 and not hostile and
            opp_d < n * 0.45 and my_c_next_d <= 2):
            return 'C'

    return 'D'
